  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "other",
      "direction": "multi-phase structural break",
      "magnitude": "A/E swings from ~1.20 (2015–2017) to ~0.30 (2019–2020), then recovers to ~1.25 (2021–2024); all yearly deviations exceed 5σ under Poisson",
      "confidence": 1.0,
      "evidence": [
        "artifacts/ae_ip_by_year.csv: sustained high A/E (1.19–1.21) in 2015–2017, abrupt drop in 2018 (0.814), deep trough in 2019–2020 (0.24–0.36), sharp return to high level (1.23–1.26) from 2021 onward",
        "Poisson σ ≈ 0.025–0.031 across the period; observed deviations are 6–30σ, completely ruling out sampling noise",
        "artifacts/ae_ip_termination.csv shows termination A/E ≈ 1.0 across all diagnoses, confirming the anomaly is driven by incidence/severity or exposure misalignment rather than recovery rates"
      ],
      "recommended_action": "Prioritize data integrity verification (exposure alignment, claims lag/allocation, policy year vs calendar year boundaries, and any major system migrations). If data is confirmed accurate, investigate business changes around 2018 and 2021 (product redesign, benefit caps, underwriting rule changes, or catastrophic claim events). Update pricing and valuation assumptions to reflect the post-2021 higher claim trend and explicitly model the observed volatility."
    }
  ]
}

